// Des: Send job: send one text once, verify, log failures
// Flo: mode check > halt+pace gate > open chat > failed-chat refusal > begin send row > type + read back > popup check > click send > verify not failed > mark sent
// I/O: Sess + chat name + text (caller) > Out (sent, dup, dry); rows in sends, acts, logz, chatf
// ===================================================================
const std = @import("std"); const snap = @import("ru-page-snap.zig"); const sess = @import("ru-sess-ctxz.zig"); const rd = @import("ru-chat-read.zig"); const priv = @import("ru-safe-priv.zig"); const opn = @import("ru-chat-open.zig"); const extr = @import("ru-page-extr.zig"); const fnd = @import("ru-labl-find.zig"); const inpu = @import("ru-huma-inpu.zig"); const dial = @import("ru-page-dial.zig"); const flo = @import("st-flow-data.zig");
const CF = .{ .vfy = 6, .dayz = 86400000 };
pub const Out = enum { sent, dup, dry };
fn bodyOf(ses: *sess.Sess, text: []const u8) []const u8 { if (fnd.selfPrefix(&ses.reg, text)) |len| return text[len..]; return text; }
fn shown(ses: *sess.Sess, text: []const u8) !bool { if (ses.reg.ext.msg_sel.len > 0) { const ms = try extr.msgsDom(ses.aren, ses.conn, ses.reg.ext); var idx: usize = ms.len; var seen: u32 = 0; while (idx > 0 and seen < CF.vfy) : (seen += 1) { idx -= 1; if (std.mem.eql(u8, ms[idx].dir, "me") and std.mem.eql(u8, bodyOf(ses, ms[idx].text), text) and !std.mem.eql(u8, ms[idx].failed, "1")) return true; } return false; } const shot = try rd.msgsNow(ses); var idx: usize = shot.len; var seen: u32 = 0; while (idx > 0 and seen < CF.vfy) : (seen += 1) { idx -= 1; if (std.mem.eql(u8, shot[idx].who, "me") and std.mem.eql(u8, shot[idx].body, text)) return true; } return false; }
fn lastFailed(ses: *sess.Sess, text: []const u8) !bool { if (ses.reg.ext.msg_sel.len == 0) return false; const ms = try extr.msgsDom(ses.aren, ses.conn, ses.reg.ext); var idx: usize = ms.len; var seen: u32 = 0; while (idx > 0 and seen < CF.vfy) : (seen += 1) { idx -= 1; if (std.mem.eql(u8, ms[idx].dir, "me") and std.mem.eql(u8, bodyOf(ses, ms[idx].text), text)) return std.mem.eql(u8, ms[idx].failed, "1"); } return false; }
fn verify(ses: *sess.Sess, text: []const u8) !bool { var cnt: u32 = 0; while (cnt < ses.cfg.retr_coun_maxz) : (cnt += 1) { if (try shown(ses, text)) return true; if (try lastFailed(ses, text)) return false; std.Io.sleep(ses.iozz, .fromMilliseconds(if (ses.fast) 1 else 500), .awake) catch {}; } return false; }
fn exists(ses: *sess.Sess, name: []const u8) !bool { _ = opn.locate(ses, name) catch |err| { if (err == error.NoElem) return false; return err; }; return true; }
fn composer(ses: *sess.Sess) !?[]const u8 { if (ses.reg.ext.comp_sel.len == 0) return null; const js = try std.fmt.allocPrint(ses.aren, "(function(){{var e=document.querySelector({s});return e?(e.tagName!=='DIV'&&e.value!==undefined?e.value:e.innerText):''}})()", .{try std.json.Stringify.valueAlloc(ses.aren, ses.reg.ext.comp_sel, .{})}); return try snap.evalStr(ses.aren, ses.conn, js); }
pub fn same(got: []const u8, want: []const u8) bool { var gb: [4096]u8 = undefined; var wb: [4096]u8 = undefined; return std.mem.eql(u8, norm(&gb, got), norm(&wb, want)); }
fn norm(buf: []u8, txt: []const u8) []const u8 { var len: usize = 0; var idx: usize = 0; while (idx < txt.len and len < buf.len) { if (idx + 1 < txt.len and txt[idx] == 0xC2 and txt[idx + 1] == 0xA0) { buf[len] = 0x20; len += 1; idx += 2; } else { buf[len] = txt[idx]; len += 1; idx += 1; } } return std.mem.trim(u8, buf[0..len], " \r\n\t"); }
pub fn mentionAt(text: []const u8, from: usize) ?usize { var idx = from; while (idx < text.len) : (idx += 1) { if (text[idx] == '@' and (idx == 0 or text[idx - 1] == ' ') and idx + 1 < text.len and std.ascii.isAlphanumeric(text[idx + 1])) return idx; } return null; }
pub fn mentionName(text: []const u8, at: usize) []const u8 { var end = at + 1; while (end < text.len and text[end] != ' ' and text[end] != ',' and text[end] != '.' and text[end] != '!' and text[end] != '?') end += 1; return text[at + 1 .. end]; }
fn typeMentions(ses: *sess.Sess, text: []const u8) !void { var pos: usize = 0; while (mentionAt(text, pos)) |at| { if (at > pos) try ses.typeIn(text[pos..at]); const name = mentionName(text, at); try ses.typeIn(try std.fmt.allocPrint(ses.aren, "@{s}", .{name})); ses.readPause(); const lst = try ses.nodes(); var picked = false; for (lst) |nod| { if (std.ascii.eqlIgnoreCase(nod.role, "option") and std.ascii.eqlIgnoreCase(nod.name, name)) { try ses.clickNode(nod); picked = true; break; } } pos = at + 1 + name.len; if (picked and pos < text.len and text[pos] == ' ') { const cur = (try composer(ses)) orelse ""; if (std.mem.endsWith(u8, cur, " ") or std.mem.endsWith(u8, cur, " ")) pos += 1; } if (!picked) ses.logz("warn", "mention not found, typed as text"); } if (pos < text.len) try ses.typeIn(text[pos..]); }
fn typeChecked(ses: *sess.Sess, text: []const u8) !void { if (mentionAt(text, 0) != null) { try typeMentions(ses, text); } else try ses.typeIn(text); const got = (try composer(ses)) orelse return; if (same(got, text)) return; ses.logz("warn", "composer text differs, retrying once"); const box = try ses.findKey("mesg_boxz"); try ses.clickNode(box); try inpu.clearField(ses.aren, ses.conn); if (mentionAt(text, 0) != null) { try typeMentions(ses, text); } else try ses.typeIn(text); const again = (try composer(ses)) orelse return; if (same(again, text)) return; try inpu.clearField(ses.aren, ses.conn); ses.logz("error", "composer text still differs, nothing sent"); return error.Fail; }
fn streakHalt(ses: *sess.Sess) !void { const strk = try flo.metaInt(ses.sto, ses.aren, "fail_strk", 0) + 1; try flo.metaPutInt(ses.sto, "fail_strk", strk); if (strk >= ses.cfg.fail_strk_maxz) { try ses.sto.haltSet(ses.now(), "failed-send streak"); try ses.sto.metaSet("halt_class", "unsf"); ses.logz("halt", "failed-send streak"); return error.Halted; } }
pub fn sendText(ses: *sess.Sess, chat: []const u8, text: []const u8) !Out { const trim = std.mem.trim(u8, text, " \r\n\t"); if (trim.len == 0 or chat.len == 0) return error.BadJob; if (ses.mode == .read) return error.BadUsage; if (ses.mode == .dry) { try ses.pre(.read); if (!try exists(ses, chat)) return error.NoElem; const note = try std.fmt.allocPrint(ses.aren, "PREVIEW {s}: {s}", .{ chat, priv.bodyLog(ses.aren, trim, ses.cfg.logz_body_enab) }); ses.logz("info", note); return .dry; }
try ses.pre(.send); const opened = try opn.openChat(ses, chat); const canon = opened.name; if (opened.stran) try ses.pre(.newc); if (try flo.chatFailedSince(ses.sto, canon, ses.now() - CF.dayz)) return error.ChatFailed; const beg = try ses.sto.sendBegin(canon, trim, ses.now()); if (beg == .dup) { ses.logz("info", "duplicate send skipped"); return .dup; }
if (beg == .pend and try shown(ses, trim)) { try ses.sto.sendDone(canon, trim, ses.now()); ses.logz("info", "resumed: message already in chat"); return .sent; }
const box = try ses.findKey("mesg_boxz"); try ses.clickNode(box); try typeChecked(ses, trim); ses.readPause(); _ = try dial.check(ses); ses.fire("before_click"); const btn = try ses.findKey("send_butt"); try ses.clickNode(btn); ses.fire("after_click");
if (!try verify(ses, trim)) { if (try lastFailed(ses, trim)) { try flo.chatFailMark(ses.sto, canon, ses.now()); ses.logz("error", "send failed in chat, not retried"); try streakHalt(ses); return error.ChatFailed; } ses.logz("error", "send not confirmed in chat"); return error.Fail; }
try flo.metaPutInt(ses.sto, "fail_strk", 0); try ses.sto.sendDone(canon, trim, ses.now()); const note = try std.fmt.allocPrint(ses.aren, "sent to {s}: {d} chars", .{ canon, trim.len }); ses.logz("info", note); ses.pause(); return .sent; }
